import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TextSense — NLP Microservice","description":"Sentiment analysis microservice with a transformer backend and a deterministic lexicon fallback: batch inference, caching, Prometheus metrics, offline tests.","frontmatter":{"title":"TextSense — NLP Microservice","description":"Sentiment analysis microservice with a transformer backend and a deterministic lexicon fallback: batch inference, caching, Prometheus metrics, offline tests."},"headers":[],"relativePath":"en/projects/textsense/index.md","filePath":"en/projects/textsense/index.md"}`),a={name:`en/projects/textsense/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="textsense-—-nlp-microservice" tabindex="-1">TextSense — NLP Microservice <a class="header-anchor" href="#textsense-—-nlp-microservice" aria-label="Permalink to “TextSense — NLP Microservice”">​</a></h1><p><strong><a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">TextSense</a></strong> is what an ML service looks like when a backend engineer builds it: the model is the easy part, and everything around it — health probes, metrics, graceful degradation, payload hardening — is the actual engineering.</p><h2 id="the-fallback-is-the-feature" tabindex="-1">The fallback is the feature <a class="header-anchor" href="#the-fallback-is-the-feature" aria-label="Permalink to “The fallback is the feature”">​</a></h2><p>Most NLP &quot;APIs&quot; die the day the model download fails. TextSense wraps inference in a <strong>strategy pattern</strong>: it tries the <code>transformers</code> backend (DistilBERT SST-2 on CPU) and, if torch is unavailable or inference throws, degrades to a <strong>deterministic lexicon engine</strong> written in pure stdlib. The HTTP contract never changes — every response carries a <code>model</code> id (<code>distilbert-sst2</code> or <code>lexicon-v1</code>) so callers know who answered and can decide what the reduced confidence means for them.</p><p>The lexicon engine is genuinely useful too: negation handling, intensifiers, punctuation emphasis — deterministic enough that the entire test suite runs <strong>offline in under a second</strong>, no gigabyte downloads, no GPU.</p><h2 id="what-the-service-ships" tabindex="-1">What the service ships <a class="header-anchor" href="#what-the-service-ships" aria-label="Permalink to “What the service ships”">​</a></h2><ul><li><code>POST /api/v1/sentiment</code> — single text → label, confidence, latency, request id</li><li><code>POST /api/v1/sentiment/batch</code> — up to 64 texts, order preserved, cache-aware</li><li><code>GET /metrics</code> — Prometheus format: request counters, latency, cache hits</li><li><code>GET /health</code> — backend id + uptime for orchestrators</li><li>Optional <code>X-API-Key</code> auth, payload caps with honest <code>413</code>s</li></ul><h2 id="why-this-belongs-in-my-portfolio" tabindex="-1">Why this belongs in my portfolio <a class="header-anchor" href="#why-this-belongs-in-my-portfolio" aria-label="Permalink to “Why this belongs in my portfolio”">​</a></h2><p>Because &quot;AI Specialist&quot; claims are cheap and running services are not. TextSense shows the full path: model choice, fallback strategy, batch coalescing, response caching, metrics exposition and a test suite that treats determinism as a feature. It pairs with <a href="/Usf/en/projects/taskflow-api/">TaskFlow API</a> as the ML sibling of my backend stack.</p><div class="tip custom-block"><p class="custom-block-title">Try it</p><p><code>docker compose up --build</code>, then post a sentence to <code>/api/v1/sentiment</code> — <a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">github.com/Godde3s/textsense</a></p></div>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};